    features_detail: [
      { level: 1, name_pl: "Inspiracja Barda", name_en: "Bardic Inspiration", desc_pl: "Jako akcja dodatkowa inspirujesz istotę w zasięgu 60 stóp kością Inspiracji (k6 -> k8 -> k10 -> k12). W ciągu 10 minut może dodać ją do testu cechy, rzutu ataku lub rzutu obronnego. Użycia: modyfikator z Charyzmy.", desc_en: "Bonus action to give a creature within 60 ft a Bardic Inspiration die (d6 to d12) to add to an ability check, attack roll, or saving throw." },
      { level: 2, name_pl: "Człowiek Renesansu", name_en: "Jack of All Trades", desc_pl: "Dodajesz połowę swojej premii z biegłości (zaokrągloną w dół) do każdego testu cechy (w tym Inicjatywy!), w którym nie posiadasz biegłości.", desc_en: "Add half your proficiency bonus, rounded down, to any ability check you make that doesn't already include your proficiency bonus." },
      { level: 10, name_pl: "Magiczne Sekrety", name_en: "Magical Secrets", desc_pl: "Wybierasz dwa zaklęcia z dowolnej klasy w grze (np. Kontrzaklęcie, Kula Ognia, Znalezienie Rumaka) i dodajesz je do swoich znanych zaklęć Barda.", desc_en: "Choose two spells from any classes, including this one, to learn as Bard spells." }
    ],
    subclasses: [
      { id: "lore", name_pl: "Kolegium Wiedzy", name_en: "College of Lore", source: "PHB", desc_pl: "Dodatkowe 3 biegłości w umiejętnościach, Cięte Słowa (Cutting Words) obniżające rzuty wrogów oraz Dodatkowe Magiczne Sekrety już na 6. poziomie.", desc_en: "Gain 3 bonus skills, Cutting Words to subtract Inspiration from enemy rolls, and Additional Magical Secrets at level 6." },
      { id: "valor", name_pl: "Kolegium Waleczności", name_en: "College of Valor", source: "PHB", desc_pl: "Biegłość w średnich pancerzach, tarczach i broni żołnierskiej, Inspiracja Bojowa do obrażeń/KP oraz Dodatkowy Atak na 6. poziomie.", desc_en: "Gain medium armor, shields, martial weapons, Combat Inspiration, and Extra Attack at level 6." },
      { id: "swords", name_pl: "Kolegium Mieczy", name_en: "College of Swords", source: "XGE", desc_pl: "Mistrzowie popisów ostrzem (Blade Flourish: Obronna, Rozpłatania, Mobilna), styl walki oraz Dodatkowy Atak na 6. poziomie.", desc_en: "Blade Flourishes (Defensive, Slashing, Mobile) enhance weapon attacks and AC, with Extra Attack at level 6." },
      { id: "eloquence", name_pl: "Kolegium Elokwencji", name_en: "College of Eloquence", source: "TCE", desc_pl: "Srebrny Język (minimalny rzut na Perswazję i Oszustwo to 10 na kości k20) oraz Niepokojące Słowa obniżające rzut obronny wroga.", desc_en: "Silver Tongue treats any roll of 9 or lower on Persuasion/Deception as a 10, and Unsettling Words penalizes enemy saving throws." },
      { id: "glamour", name_pl: "Kolegium Uroku", name_en: "College of Glamour", source: "XGE", desc_pl: "Magia Feywild zapewniająca tymczasowe PW i darmowy ruch dla całej drużyny (Mantle of Inspiration).", desc_en: "Weave fey magic with Mantle of Inspiration granting temporary HP and reaction movement to allies." },
      { id: "creation", name_pl: "Kolegium Stworzenia", name_en: "College of Creation", source: "TCE", desc_pl: "Tworzenie przedmiotów z niczego i ożywianie obiektów do walki po stronie drużyny.", desc_en: "Draw on the Song of Creation to conjure items and animate dancing objects." },
      { id: "whispers", name_pl: "Kolegium Szeptów", name_en: "College of Whispers", source: "XGE", desc_pl: "Szpiedzy używający Psychicznych Ostrzy (dodatkowe obrażenia psychiczne jak Ukradkowy Atak) oraz kradnący cienie i tożsamość.", desc_en: "Use Psychic Blades for burst psychic damage and capture shadows to assume identities." }
    ]
